UPDATE articles SET content = jsonb_set(content, '{root,children}', COALESCE((SELECT jsonb_agg(CASE idx WHEN 25 THEN $e${"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"（具体租金、房源情况以实际签约为准）","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}$e$::jsonb WHEN 5 THEN $e${"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"项目全称：鸿寿坊企业天地，位于上海市普陀区新会路186号，为瑞安房地产2023年投用的城市更新商办项目，无中介费； 办公产品分双塔：东塔25层配VAV中央空调，物业费36元/㎡/月；西塔11层独栋配24小时独立VRV空调，物业费25元/㎡/月，整体得房率70%，获LEED+WELL双金级认证； 租金区间5-9元/㎡/天，70㎡起租、最大可租整栋1850㎡，配套1.5万㎡石库门商业、825个车位，车位月租1000-1500元； 交通硬指标：步行150米达7/13号线长寿路站，距北横通道入口近，自驾20分钟到虹桥枢纽，距静安寺1.5公里； 物业为瑞安丰诚物业，已入驻企业包含世界500强及传媒、教育、互联网领域头部机构。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}$e$::jsonb WHEN 1 THEN $e${"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"如果您正在普陀区长寿路附近寻找品牌背书强、通勤便利、配套成熟的高品质办公空间，位于普陀区新会路186号的 鸿寿坊企业天地 是企业布局市中心、控制办公成本的优质选择。作为瑞安房地产高端“企业天地”产品线标杆、普陀区城市更新重点项目，项目2023年7月全新竣工，融合百年石库门里弄肌理与现代甲级办公标准，打造兼具文化调性与商务效率的“普陀新天地”商办综合体，距静安寺、南京西路核心商圈仅1.5公里，办公性价比远超核心商务区。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}$e$::jsonb ELSE elem END ORDER BY idx) FROM jsonb_array_elements(content->'root'->'children') WITH ORDINALITY AS t(elem, idx) WHERE idx NOT IN (2,20,26,27)), '[]'::jsonb)), updated_at = now() WHERE id = 57 AND md5(content::text) = 'c0d0159cfaa86634dba39612b56aed97';
UPDATE articles SET content = jsonb_set(content, '{root,children}', COALESCE((SELECT jsonb_agg(CASE idx WHEN 20 THEN $e${"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"（具体租金、房源情况以实际签约为准）","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}$e$::jsonb WHEN 4 THEN $e${"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"项目标准名称为旭辉企业大厦（推广名CIFI TOWER），位于上海普陀区长寿路与常德路交口； 项目为8万方甲级商务综合体，其中办公3.7万方、商业2万方，获LEED金+WELL金+国家绿色二星三重认证，由Aedas、伍兹贝格联合设计； 交通为7/13号线长寿路站真正上盖，电梯直达站厅，非步行可达类项目； 现行租赁标准：租金6-7元/㎡/天，物业费34元/㎡/月（含6%专票，网传30元/㎡/月为前期不含税旧标准，已失效），车位月租1000元； 可租面积93㎡起至整层2300㎡，得房率70%，配VAV空调+24小时冷却水，部分房源带家具可拎包入驻，局部有可拆卸楼板、专属露台。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}$e$::jsonb WHEN 1 THEN $e${"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"如果您正在浦西内环寻找地铁直达、配套成熟、硬件过硬、性价比高的甲级办公空间，位于长寿路核心板块的**旭辉企业大厦（CIFI TOWER）**是企业布局市中心、平衡办公成本与品牌形象的优质选择。项目由旭辉集团打造，国际顶尖设计团队Aedas&伍兹贝格联手设计，是内环长寿路板块的生态美学商务地标，2站地铁直达静安寺、3站到南京西路，以核心区6元/㎡/天起的租金、24小时空调配套、全成熟商业生态，为企业提供低门槛高品质办公体验。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}$e$::jsonb ELSE elem END ORDER BY idx) FROM jsonb_array_elements(content->'root'->'children') WITH ORDINALITY AS t(elem, idx) WHERE idx NOT IN (2,15,21,22)), '[]'::jsonb)), updated_at = now() WHERE id = 56 AND md5(content::text) = '986f12fc02ab21db7de6b1dc8ac24234';
