UPDATE articles SET content = jsonb_set(content, '{root,children}', COALESCE((SELECT jsonb_agg(CASE idx WHEN 25 THEN $e${"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"项目坐标：  上海市杨浦区杨树浦路 - 安浦路之间（18 号线丹阳路站步行可达）","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"招商状态：  D 栋塔楼正式对外招商，整层及中小面积灵活分割可选","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"listType":"bullet","direction":"ltr"}$e$::jsonb ELSE elem END ORDER BY idx) FROM jsonb_array_elements(content->'root'->'children') WITH ORDINALITY AS t(elem, idx) WHERE idx NOT IN (3,8,22,23,27,28)), '[]'::jsonb)), updated_at = now() WHERE id = 54 AND md5(content::text) = '9f0777498ff69e77c2a87af8f7d4f3c7';
UPDATE articles SET content = jsonb_set(content, '{root,children}', COALESCE((SELECT jsonb_agg(CASE idx WHEN 22 THEN $e${"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"2. 预租专属优惠与战略锁定建议  目前项目处于 2026 年交付前的预租阶段，这是锁定优质房源的最佳窗口期。预租客户不仅可优先挑选高区一线江景房源，享受视野与采光的最优解，更有机会获得预租专属优惠，降低初始入驻成本。考虑到 2026 年交付后西岸区域成熟度将进一步跃升，租金上涨预期明显，提前锁定意味着锁定了未来的资产增值空间 。建议有意向的企业尽快对接招商中心，进行实地勘察与需求匹配，以免错失高区稀缺户型。东航滨江之门，不仅是办公空间，更是企业资产组合中的优质标的，值得远见者提前布局。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}$e$::jsonb WHEN 2 THEN $e${"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"在上海写字楼市场进入存量优化与品质升级并行的当下，企业选址已不再仅仅是物理空间的租赁，更是品牌势能、产业生态与资产价值的战略抉择。 东航滨江之门 ，作为中国东方航空资产管理有限公司倾力打造的徐汇西岸核心甲级办公楼，不仅承载着东航品牌的深厚底蕴，更占据了上海“一江一河”战略中徐汇滨江黄金岸线的关键节点。项目直面黄浦江一线江景，于 2026 年 12 月正式交付，正处于预租黄金窗口期。对于追求稳健资产背书、渴望融入人工智能与金融科创集群的远见型企业而言，这里不仅是办公场所，更是通往未来商业版图的门户。本项目依托东航央企背景，提供超越传统写字楼的安全感与稳定性，同时深度融合徐汇“模速空间”人工智能创新生态，为科创、金融及航空产业链企业提供无可复制的圈层资源。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}$e$::jsonb ELSE elem END ORDER BY idx) FROM jsonb_array_elements(content->'root'->'children') WITH ORDINALITY AS t(elem, idx) WHERE idx NOT IN (3,8,12,16,17,20,21)), '[]'::jsonb)), updated_at = now() WHERE id = 53 AND md5(content::text) = 'dc91dd4b347f991277845b7ed33d1aed';
UPDATE articles SET content = jsonb_set(content, '{root,children}', COALESCE((SELECT jsonb_agg(CASE idx WHEN 1 THEN $e${"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"项目地址 ：上海市闵行区虹桥前湾板块鹤龙桥路289弄","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}$e$::jsonb ELSE elem END ORDER BY idx) FROM jsonb_array_elements(content->'root'->'children') WITH ORDINALITY AS t(elem, idx) WHERE idx NOT IN (2,7,12,27,32,33,34)), '[]'::jsonb)), updated_at = now() WHERE id = 52 AND md5(content::text) = '4276232ccaa7c938ec4cf8b840fdf576';
UPDATE articles SET content = jsonb_set(content, '{root,children}', COALESCE((SELECT jsonb_agg(CASE idx WHEN 19 THEN $e${"tag":"ol","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"灵活租赁方案与成本优化策略  项目支持多种租赁模式，1 号楼 6-8F 整层毛坯出租，3-5F 可分割为小单元标准交付，满足不同规模企业的空间需求。2 号楼整栋毛坯出租，专为总部型研发办公需求定制，适合需要独立冠名与形象展示的大型企业。4 号楼 4-5F 为精装小户型可拎包入住，6-7F 为标准交付小户型单元，极大降低了初创团队与项目组的初始装修成本与时间成本。这种灵活性确保了企业无论是初创团队扩张还是成熟集团设立分部，都能找到匹配的空间解决方案，避免了因空间不适配造成的二次装修浪费。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"专属招商服务与联系渠道  为确保企业获得最高效的对接服务，项目设立了专属招商经理对接机制。无论是咨询租赁细节、预约看房，还是了解政策扶持，均可通过官方渠道获得专业解答。我们建议有意向的企业决策者尽快行动，因为核心地段的优质房源具有稀缺性，尤其是高区景观房源与整层房源，往往在交付前即被锁定。通过提前锁定，企业不仅能获得价格优势，还能在装修期安排上掌握主动权，确保按时入驻。云南白药上海国际中心，不仅是办公空间，更是企业资产组合中的优质标的，值得远见者提前布局。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"项目地址：  上海市闵行区华漕镇雅乐路 1538 号","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"交付时间：  2026年10月","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"listType":"number","direction":"ltr"}$e$::jsonb WHEN 1 THEN $e${"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"在生物医药与大健康产业迈向全球化协作与区域化集聚的双重趋势下，企业选址已超越单纯的物理空间租赁，演变为品牌资产沉淀、产业链生态嵌入与人才战略落地的综合决策。云南白药上海国际中心，作为云南白药集团华东区域总部及全国战略布局的关键节点，不仅承载着百年民族品牌的历史底蕴，更占据了上海虹桥前湾 CBD 核心区的战略高地。项目总投资约 15.5-20 亿元，总建筑面积约 14.2 万㎡，集办公、研发、商业、人才公寓于一体，是沪滇产业合作的标杆项目。对于致力于在生物医药、大健康及科技创新领域深耕的企业而言，入驻此处不仅是选择了一处办公地点，更是选择了一种与行业龙头共成长、与长三角一体化发展同频共振的发展模式。","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}$e$::jsonb ELSE elem END ORDER BY idx) FROM jsonb_array_elements(content->'root'->'children') WITH ORDINALITY AS t(elem, idx) WHERE idx NOT IN (2,11,16,20,21)), '[]'::jsonb)), updated_at = now() WHERE id = 51 AND md5(content::text) = 'fc1ee67c5c20fd6b899d7fda1781b5e2';
